+/**
+ * Safely multiplies two size_t values with overflow checking.
+ * Returns std::nullopt if overflow would occur.
+ */
+inline std::optional<size_t> safe_multiply(size_t a, size_t b) {
+  if (a == 0 || b == 0) {
+    return 0;
+  }
+  if (a > std::numeric_limits<size_t>::max() / b) {
+    return std::nullopt;
+  }
+  return a * b;
+}
+
+/**
+ * Safely multiplies multiple size_t values with overflow checking.
+ * Returns std::nullopt if overflow would occur.
+ */
+inline std::optional<size_t> safe_multiply(const std::vector<size_t>& values) {
+  size_t result = 1;
+  for (size_t v : values) {
+    auto opt = safe_multiply(result, v);
+    if (!opt) {
+      return std::nullopt;
+    }
+    result = *opt;
+  }
+  return result;
+}
+
 } // namespace tensor_util
 } // namespace exec_aten
 } // namespace runtime
