@@ -0,0 +1,89 @@
+import { NodeOperationError } from 'n8n-workflow';
+
+/**
+ * Secure Python sandbox runner with restricted imports and execution
+ */
+export class PythonSandboxRunner {
+	private readonly allowedModules = new Set([
+		'json',
+		'math',
+		'datetime',
+		'collections',
+		'itertools',
+		'functools',
+		'operator',
+		'copy',
+		'random',
+		'string',
+		're',
+		'decimals',
+		'fractions',
+	]);
+
+	private readonly restrictedModules = new Set([
+		'subprocess',
+		'os',
+		'sys',
+		'importlib',
+		'ctypes',
+		'pickle',
+		'marshal',
+		'platform',
+		'socket',
+		'urllib',
+		'urllib2',
+		'httplib',
+		'ftplib',
+		'smtpd',
+		'smtplib',
+		'poplib',
+		'imaplib',
+		'xmlrpc',
+		'webbrowser',
+		'getpass',
+		'pwd',
+		'grp',
+		'shutil',
+		'tempfile',
+		'glob',
+		'pathlib',
+		'fileinput',
+		'filecmp',
+		'zipfile',
+		'tarfile',
+		'gzip',
+		'bz2',
+		'zlib',
+	]);
+
+	async execute(code: string, inputData: any): Promise<any> {
+		// Validate code before execution
+		this.validateCode(code);
+
+		// Execute in restricted environment
+		const restrictedBuiltins = this.createRestrictedBuiltins();
+
+		try {
+			// Use exec with restricted globals and builtins
+			const globals = {
+				'__builtins__': restrictedBuiltins,
+				'input': inputData,
+				'output': [],
+			};
+
+			// Execute code in sandboxed environment
+			const compiled = compile(code, '<string>', 'exec');
+			exec(compiled, globals);
+
+			return globals.output;
+		} catch (error) {
+			throw new NodeOperationError(
+				null,
+				`Python execution failed: ${error.message}`,
+				{ level: 'error' }
+			);
+		}
+	}
+
+	private validateCode(code: string): void {
+		// Check for dangerous patterns
+		const dangerousPatterns = [
+			/__import__\s*\(/,
+			/importlib\./,
+			/__builtin__/,
+			/__builtins__/,
+			/eval\s*\(/,
+			/exec\s*\(/,
+			/compile\s*\(/,
+		];
+
+		for (const pattern of dangerousPatterns) {
+			if (pattern.test(code)) {
+				throw new NodeOperationError(
+					null,
+					'Unsafe Python code detected: dangerous pattern found',
+					{ level: 'error' }
+				);
+			}
+		}
+	}
+
+	private createRestrictedBuiltins(): any {
+		const safeBuiltins = {};
+		const allowedBuiltins = [
+			'abs', 'all', 'any', 'bin', 'bool', 'bytes', 'callable', 'chr',
+			'dict', 'dir', 'divmod', 'enumerate', 'filter', 'float', 'format',
+			'frozenset', 'getattr', 'hasattr', 'hash', 'hex', 'id', 'int',
+			'isinstance', 'issubclass', 'iter', 'len', 'list', 'map', 'max',
+			'min', 'next', 'oct', 'ord', 'pow', 'print', 'range', 'repr',
+			'reversed', 'round', 'set', 'slice', 'sorted', 'str', 'sum',
+			'tuple', 'type', 'zip',
+		];
+
+		for (const name of allowedBuiltins) {
+			if (typeof globalThis[name] !== 'undefined') {
+				safeBuiltins[name] = globalThis[name];
+			}
+		}
+
+		return safeBuiltins;
+	}
+}
+
+export function createSandboxedPythonRunner(): PythonSandboxRunner {
+	return new PythonSandboxRunner();
+}

