+++ b/src/safe-eval.ts
@@ -0,0 +1,45 @@
+import { DataArray, DataObject, DataValue } from "./data";
+
+/**
+ * Safe evaluation function that prevents arbitrary code execution
+ * Only allows safe operations on data values
+ */
+export function safeEval(code: string, context: any): any {
+    // Whitelist of allowed operations
+    const allowedOperations = [
+        "map", "filter", "reduce", "find", "findIndex",
+        "some", "every", "includes", "indexOf", "lastIndexOf",
+        "length", "toString", "valueOf", "concat", "slice",
+        "join", "split", "trim", "toLowerCase", "toUpperCase"
+    ];
+
+    // Check for dangerous patterns
+    const dangerousPatterns = [
+        /eval\s*\(/,
+        /Function\s*\(/,
+        /setTimeout\s*\(/,
+        /setInterval\s*\(/,
+        /require\s*\(/,
+        /import\s*\(/,
+        /process\s*\./,
+        /global\s*\./,
+        /window\s*\./,
+        /document\s*\./,
+        /constructor\s*\./,
+        /prototype\s*\./
+    ];
+
+    for (const pattern of dangerousPatterns) {
+        if (pattern.test(code)) {
+            throw new Error("Unsafe code pattern detected");
+        }
+    }
+
+    // Execute in a restricted sandbox
+    const sandbox = new Function("context", `
+        "use strict";
+        return (${code});
+    `);
+
+    return sandbox(context);
+}

