+  'Etc/UTC', 'Etc/GMT', 'Etc/GMT+0', 'Etc/GMT-0', 'SYSTEM', 'LOCAL', 'DEFAULT'
+]);
+
+/**
+ * Validates timezone parameter to prevent code injection
+ * @param {string} timezone - The timezone value to validate
+ * @returns {boolean} - True if timezone is valid, false otherwise
+ */
+function isValidTimezone(timezone) {
+  if (typeof timezone !== 'string') {
+    return false;
+  }
+
+  // Reject empty strings
+  if (timezone.length === 0) {
+    return false;
+  }
+
+  // Check against whitelist
+  if (VALID_TIMEZONES.has(timezone)) {
+    return true;
+  }
+
+  return false;
+}
+
+module.exports = { isValidTimezone };
