+/**
+ * Safe regex validation to prevent ReDoS attacks
+ * Checks for patterns that could cause catastrophic backtracking
+ */
+
+// Common patterns that indicate potential ReDoS
+const REDOS_PATTERNS = [
+  // Nested quantifiers like (a+)+
+  /\(\??\w+\+\)\+/,
+  // Alternation with quantifiers like (a|a)+
+  /\(\??\w+\|\w+\)\+/,
+  // Complex nested groups with quantifiers
+  /\(\??\(\??\w+\)\+\)\+/,
+  // Repetitive alternation
+  /\(\??\w+\|\w+\|\w+\)\+/,
+]
+
+export function isSafePattern(pattern: string): boolean {
+  // Check for known ReDoS patterns
+  for (const redosPattern of REDOS_PATTERNS) {
+    if (redosPattern.test(pattern)) {
+      return false
+    }
+  }
+  
+  // Check for excessive length
+  if (pattern.length > 1000) {
+    return false
+  }
+  
+  // Check for excessive nesting depth
+  const depth = getRegexDepth(pattern)
+  if (depth > 10) {
+    return false
+  }
+  
+  return true
+}
+
+function getRegexDepth(pattern: string): number {
+  let depth = 0
+  let maxDepth = 0
+  for (const char of pattern) {
+    if (char === '(') {
+      depth++
+      maxDepth = Math.max(maxDepth, depth)
+    } else if (char === ')') {
+      depth--
+    }
+  }
+  return maxDepth
+}
